mapper.select:
SELECT FROM () t
t.offering_status='active' AND t.publication_state='published' AND t.assignment_state IN ('NOT_STARTED','IN_PROGRESS') t.assignment_state IN ('SUBMITTED','REVIEWED')
ORDER BY t.due_at,t.id LIMIT #{size} OFFSET #{offset}

SELECT id,assignment_id,offering_id,attempt_no AS attempt_number,workspace_revision,submitted_at,is_late AS late,CASE WHEN is_current=0 THEN 1 ELSE 0 END AS superseded,'none' AS feedback_status
FROM submissions WHERE assignment_id=#{assignmentId} AND student_id=#{studentId}
ORDER BY attempt_no DESC LIMIT #{size} OFFSET #{offset}

SELECT id,offering_id,chapter_id,title,description,estimated_minutes,type,status,is_required,due_at,late_until,allow_resubmit,max_attempts,max_score,content_version,current_ai_policy_id,published_at,created_by,created_at,updated_at
FROM assignments WHERE offering_id=#{offeringId}
AND status=#{publicationState}
ORDER BY created_at DESC,id DESC LIMIT #{size} OFFSET #{offset}

SELECT c.id,c.offering_id,c.position,c.title,c.summary,c.status,c.is_required,c.content_version,c.published_at FROM chapters c JOIN offering_members m ON m.offering_id=c.offering_id WHERE m.user_id=#{userId} AND m.role='student' AND m.status='active' AND c.status='published' AND m.last_chapter_id IS NOT NULL AND c.id=m.last_chapter_id
JOIN course_offerings o ON o.id=c.offering_id WHERE o.term_id=#{termId}
ORDER BY m.last_studied_at DESC LIMIT 1

mapper.update:
UPDATE notifications SET is_read=1,read_at=#{readAt,typeHandler=com.learningplatform.common.mybatis.UtcInstantTypeHandler}
WHERE recipient_id=#{recipientId} AND is_read=0
AND related_offering_id=#{offeringId}
AND type=#{type}
